package objetos.orientacao.varargs.domain;public class Calculadora {    public void somaNumeros(int[] numeros){        int soma = 0;        for (int s : numeros){            soma += s;        }        System.out.println(soma);    }    public void somaNumerosVarArgs(int... numeros){        int somarVarArgs = 0;        for (int s : numeros){            somarVarArgs += s;        }        System.out.println(somarVarArgs);    }}